-- mod-lan: Blackrock Depths for the adventure route. Every mob in Blackrock Depths drops the Shadowforge Key (11000)
-- for players who don't have it, so nobody needs the Dark Iron Legacy quest to open the Shadowforge doors on the
-- way to Emperor Dagran Thaurissan.
-- The loot ids are those of the creatures spawned on map 230; the map condition keeps the drop inside Blackrock
-- Depths for creatures that also stand elsewhere.

DELETE FROM `creature_loot_template` WHERE `Item` = 11000 AND `Entry` IN (8889, 8890, 8891, 8892, 8893, 8894, 8895, 8896, 8897, 8898, 8899, 8900, 8902, 8903, 8904, 8905, 8906, 8907, 8908, 8909, 8910, 8911, 8912, 8913, 8914, 8915, 8916, 8920, 8921, 8922, 8923, 8929, 8983, 9016, 9017, 9018, 9019, 9024, 9025, 9033, 9041, 9042, 9056, 9156, 9319, 9499, 9502, 9537, 9541, 9543, 9545, 9547, 9554, 9677, 9678, 9680, 9681, 9938, 9956, 10043, 23872);

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 1 AND `SourceEntry` = 11000 AND `SourceGroup` IN (8889, 8890, 8891, 8892, 8893, 8894, 8895, 8896, 8897, 8898, 8899, 8900, 8902, 8903, 8904, 8905, 8906, 8907, 8908, 8909, 8910, 8911, 8912, 8913, 8914, 8915, 8916, 8920, 8921, 8922, 8923, 8929, 8983, 9016, 9017, 9018, 9019, 9024, 9025, 9033, 9041, 9042, 9056, 9156, 9319, 9499, 9502, 9537, 9541, 9543, 9545, 9547, 9554, 9677, 9678, 9680, 9681, 9938, 9956, 10043, 23872);
